/* Fixed GT06N Adapter with proper packet parsing */
const f = require('../functions');

exports.protocol = 'GT06N';
exports.model_name = 'GT06N';
exports.compatible_hardware = ['GT06N', 'GT06', 'GT06E'];

var adapter = function (device) {
  if (!(this instanceof adapter)) {
    return new adapter(device);
  }

  this.format = {'start': '(', 'end': ')', 'separator': ''};
  this.device = device;
  this.__count = 1;

  /*******************************************
   PARSE THE INCOMING DATA FROM THE DEVICE
   *******************************************/
  this.parse_data = function (data) {
    try {
      var hexData = this.bufferToHexString(data);
      console.log('Raw hex data received:', hexData);
      
      var parts = {
        'raw': hexData,
        'start': hexData.substr(0, 4)
      };

      // Check for valid start bytes
      if (parts['start'] !== '7878' && parts['start'] !== '7979') {
        console.log('Invalid start bytes:', parts['start']);
        parts.cmd = 'noop';
        parts.action = 'noop';
        parts.device_id = '';
        return parts;
      }

      // Parse packet length (1 byte after start)
      parts['length'] = parseInt(hexData.substr(4, 2), 16);
      console.log('Packet length (hex):', hexData.substr(4, 2), 'Decimal:', parts['length']);
      
      // Total packet length in hex chars = start(4) + length(2) + data(length*2) + stop(4)
      const totalHexLength = 4 + 2 + (parts['length'] * 2) + 4;
      
      // Check if we have complete packet
      if (hexData.length < totalHexLength) {
        console.log(`Incomplete packet: Have ${hexData.length}, need ${totalHexLength} hex chars`);
        parts.cmd = 'noop';
        parts.action = 'noop';
        parts.device_id = '';
        return parts;
      }

      // Extract protocol ID
      parts['protocol_id'] = hexData.substr(6, 2);
      console.log('Protocol ID:', parts['protocol_id']);
      
      // Extract data (everything between protocol and stop bytes)
      const dataStart = 8; // after start(4) + length(2) + protocol(2)
      const dataLength = parts['length'] - 1; // length includes protocol byte
      parts['data'] = hexData.substr(dataStart, dataLength * 2);
      
      // Extract stop bytes (last 4 hex chars)
      parts['stop'] = hexData.substr(hexData.length - 4, 4);
      console.log('Stop bytes:', parts['stop']);

      // Map protocol IDs to actions
      switch(parts['protocol_id']) {
        case '01': // Login packet
          // IMEI is first 8 bytes (16 hex chars) of data
          parts['device_id'] = parts['data'].substr(0, 16);
          parts.cmd = 'login_request';
          parts.action = 'login_request';
          break;
          
        case '12': // Location data
        case '22': // GPS with address
          parts.cmd = 'ping';  // Use 'ping' for compatibility
          parts.action = 'ping';
          break;
          
        case '13': // Heartbeat
          parts.cmd = 'heartbeat';
          parts.action = 'heartbeat';
          break;
          
        case '16': // Alarm data
        case '26': // Alarm with address
          parts.cmd = 'alarm';
          parts.action = 'alarm';
          break;
          
        case '17': // LBS location
          parts.cmd = 'lbs_location';
          parts.action = 'lbs_location';
          break;
          
        case '18': // Status information
          parts.cmd = 'status';
          parts.action = 'status';
          break;
          
        default:
          parts.cmd = 'noop';
          parts.action = 'noop';
          console.log('Unknown protocol:', parts['protocol_id']);
      }

      // Ensure device_id is set (for login) or empty (for other packets)
      if (!parts['device_id']) {
        parts['device_id'] = '';
      }

      console.log(`Parsed packet: Protocol=${parts['protocol_id']}, Action=${parts.action}, DeviceID=${parts.device_id || 'not set'}`);
      return parts;
    } catch (error) {
      console.error('Error parsing data:', error);
      console.error('Stack:', error.stack);
      return {
        cmd: 'noop',
        action: 'noop',
        device_id: ''
      };
    }
  };

  this.bufferToHexString = function (buffer) {
    var str = '';
    for (var i = 0; i < buffer.length; i++) {
      var hex = buffer[i].toString(16);
      str += hex.length === 1 ? '0' + hex : hex;
    }
    return str;
  };

  this.authorize = function () {
    // Login response: 7878 05 01 0001 D9DC 0D0A
    var response = '787805010001D9DC0D0A';
    console.log('Sending login response:', response);
    this.device.send(Buffer.from(response, 'hex'));
  };
  
  this.receive_heartbeat = function (msg_parts) {
    // Heartbeat response: 7878 05 13 0001 D9DC 0D0A
    var response = '787805130001D9DC0D0A';
    console.log('Sending heartbeat response:', response);
    this.device.send(Buffer.from(response, 'hex'));
  };

  // Handle ping (location data)
// In the get_ping_data function, update course parsing:
this.get_ping_data = function (msg_parts) {
  try {
    var str = msg_parts.data;
    console.log('Parsing location data, length:', str.length);
    
    // Parse date: 6 bytes (12 hex chars) - YYMMDDHHMMSS
    const dateHex = str.substr(0, 12);
    const year = parseInt(dateHex.substr(0, 2), 16) + 2000;
    const month = parseInt(dateHex.substr(2, 2), 16);
    const day = parseInt(dateHex.substr(4, 2), 16);
    const hour = parseInt(dateHex.substr(6, 2), 16);
    const minute = parseInt(dateHex.substr(8, 2), 16);
    const second = parseInt(dateHex.substr(10, 2), 16);
    const date = new Date(year, month - 1, day, hour, minute, second);
    
    // Parse satellites (1 byte)
    const satellites = parseInt(str.substr(12, 2), 16);
    
    // Parse latitude (4 bytes = 8 hex chars)
    const latHex = str.substr(14, 8);
    const latitude = parseInt(latHex, 16) / 1800000;
    
    // Parse longitude (4 bytes = 8 hex chars)
    const lngHex = str.substr(22, 8);
    const longitude = parseInt(lngHex, 16) / 1800000;
    
    // Parse speed (1 byte)
    const speed = parseInt(str.substr(30, 2), 16);
    
    // Parse course/heading (2 bytes = 4 hex chars) - Only use first byte for 0-360 range
    const courseHex = str.substr(32, 4);
    let course = parseInt(courseHex, 16);
    
    // Fix course: if it's > 360, it might be including status bits
    if (course > 360) {
      // Take only the last byte (0-255) and scale to 0-360
      course = course & 0xFF; // Get last byte
      course = (course * 360) / 255; // Scale to 0-360
    }
    
    course = Math.round(course); // Round to nearest degree
    
    // Parse status byte
    const statusByte = parseInt(str.substr(36, 2), 16);
    const statusBinary = statusByte.toString(2).padStart(8, '0');
    
    const data = {
      device_id: msg_parts.device_id || '',
      date: date.toISOString(),
      timestampDate: date,
      latitude: latitude,
      longitude: longitude,
      speed: speed,
      orientation: course, // Fixed course value
      satellites: satellites,
      raw_data: str,
      device_status: {
        power_status: statusBinary[0] === '0' ? 'normal' : 'low',
        gps_status: statusBinary[1] === '0' ? 'valid' : 'invalid',
        charge_status: statusBinary[5] === '0' ? 'not_charging' : 'charging',
        acc_status: statusBinary[6] === '1',
        armed_status: statusBinary[7] === '1'
      }
    };
    
    console.log('Parsed location:', {
      device: data.device_id,
      lat: data.latitude,
      lng: data.longitude,
      speed: data.speed,
      course: data.orientation,
      time: data.date
    });
    
    return data;
  } catch (error) {
    console.error('Error parsing ping data:', error);
    console.error('Data:', msg_parts.data);
    return false;
  }
};

  // Handle alarm data
  this.receive_alarm = function (msg_parts) {
    try {
      var str = msg_parts.data;
      console.log('Parsing alarm data, length:', str.length);
      
      // Parse date
      const dateHex = str.substr(0, 12);
      const year = parseInt(dateHex.substr(0, 2), 16) + 2000;
      const month = parseInt(dateHex.substr(2, 2), 16);
      const day = parseInt(dateHex.substr(4, 2), 16);
      const hour = parseInt(dateHex.substr(6, 2), 16);
      const minute = parseInt(dateHex.substr(8, 2), 16);
      const second = parseInt(dateHex.substr(10, 2), 16);
      const date = new Date(year, month - 1, day, hour, minute, second);
      
      // Parse satellites
      const satellites = parseInt(str.substr(12, 2), 16);
      
      // Parse latitude
      const latHex = str.substr(14, 8);
      const latitude = parseInt(latHex, 16) / 1800000;
      
      // Parse longitude
      const lngHex = str.substr(22, 8);
      const longitude = parseInt(lngHex, 16) / 1800000;
      
      // Parse speed
      const speed = parseInt(str.substr(30, 2), 16);
      
      // Parse course
      const course = parseInt(str.substr(32, 4), 16);
      
      // Parse status byte
      const statusByte = parseInt(str.substr(36, 2), 16);
      const statusBinary = statusByte.toString(2).padStart(8, '0');
      
      // Parse alarm type (1 byte)
      const alarmCode = str.substr(54, 2) || '01';
      
      const alarmTypes = {
        '01': 'SOS',
        '02': 'Low Battery',
        '03': 'Power Cut',
        '04': 'Shock',
        '05': 'Fence In',
        '06': 'Fence Out',
        '09': 'Over Speed',
        '10': 'Movement',
        '12': 'Enter Area',
        '13': 'Exit Area',
        '15': 'Power On',
        '16': 'GPS First Fix',
        '17': 'GPS Antenna Short',
        '18': 'GPS Antenna Open',
        '19': 'Power Off',
        '20': 'Sleep Mode',
        '21': 'Wake Up',
        '22': 'Door Open',
        '23': 'Door Close',
        '46': 'Temperature Alarm',
        '50': 'Vibration Alarm'
      };
      
      const alarmType = alarmTypes[alarmCode] || `Unknown Alarm: ${alarmCode}`;
      
      const data = {
        code: alarmType,
        msg: alarmType,
        device_id: msg_parts.device_id || '',
        date: date.toISOString(),
        timestampDate: date,
        latitude: latitude,
        longitude: longitude,
        speed: speed,
        orientation: course,
        satellites: satellites,
        alarm_type: alarmType,
        alarm_code: alarmCode,
        raw_data: str,
        device_status: {
          power_status: statusBinary[0] === '0' ? 'normal' : 'low',
          gps_status: statusBinary[1] === '0' ? 'valid' : 'invalid',
          charge_status: statusBinary[5] === '0' ? 'not_charging' : 'charging',
          acc_status: statusBinary[6] === '1',
          armed_status: statusBinary[7] === '1'
        }
      };
      
      console.log('Parsed alarm:', {
        device: data.device_id,
        alarm: data.alarm_type,
        lat: data.latitude,
        lng: data.longitude
      });
      
      return data;
    } catch (error) {
      console.error('Error parsing alarm data:', error);
      console.error('Data:', msg_parts.data);
      return false;
    }
  };

  // Other methods
  this.zeroPad = function (nNum, nPad) {
    return ('' + (Math.pow(10, nPad) + nNum)).slice(1);
  };
  
  this.synchronous_clock = function (msg_parts) {
    // Not implemented
  };
  
  this.run_other = function (cmd, msg_parts) {
    console.log('run_other called with cmd:', cmd);
  };

  this.request_login_to_device = function () {
    // Not implemented
  };

  this.set_refresh_time = function (interval, duration) {
    // Not implemented
  };
};

exports.adapter = adapter;